}
function mcnemar(b, c) {
  const n = b + c;
  if (n === 0) return 1.0;
  const lo = Math.min(b, c);
  const comb = (nn, k) => { let r = 1; for (let i = 0; i < k; i++) r = r * (nn - i) / (i + 1); return r; };
  let p = 0;
  for (let k = 0; k <= lo; k++) p += comb(n, k) / 2 ** n;
  return Math.min(1.0, 2 * p);
}
